// automation/src/ads-auth-normalize.js
// Validasi payload laporan iklan + konfigurasi workflow (PRD F5 §3.7).
// API key sudah divalidasi node Webhook (Header Auth). Node ini memastikan payload lengkap
// dan konfigurasi base deck terisi. Kalau gagal → balas 4xx/503 secara sinkron sehingga
// backend langsung me-rollback kredit (tidak perlu menunggu timeout 15 menit).

// ===== KONFIGURASI (diisi 3Our setelah import, lihat automation/ADS-BASE-DECK.md) =====
const CONFIG = {
  baseDeckId: 'GANTI_DENGAN_ID_BASE_DECK',        // ID Google Slides "Markimate Base Deck" (dipakai bila template tidak punya deck sendiri)
  reportsFolderId: 'GANTI_DENGAN_ID_FOLDER',       // ID folder Drive "Markimate Reports"
  graphVersion: 'v26.0',
  geminiModel: 'gemini-2.5-flash'
};
// ======================================================================================

const body = $input.first().json.body || $input.first().json;
const fail = (statusCode, error) => [{ json: { ok: false, statusCode, error, requestId: body.requestId || null } }];

if (!body.requestId || typeof body.requestId !== 'string') return fail(400, 'requestId is required');
if (!body.callbackUrl || !/^https:\/\//.test(String(body.callbackUrl))) return fail(400, 'callbackUrl (https) is required');
if (!body.template || !Array.isArray(body.template.pages) || body.template.pages.length === 0) return fail(400, 'template.pages is required');
if (body.template.pages.length > 20) return fail(400, 'template has more than 20 pages');
if (!Array.isArray(body.accounts) || body.accounts.length === 0) return fail(400, 'at least one ad account is required');

const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
const period = body.period || {};
if (!isDate(period.start) || !isDate(period.end) || period.start > period.end) return fail(400, 'period.start/end (YYYY-MM-DD) is invalid');

if (/^GANTI_/.test(CONFIG.baseDeckId) || /^GANTI_/.test(CONFIG.reportsFolderId)) {
  return fail(503, 'Ads report workflow is not configured (baseDeckId / reportsFolderId)');
}

const accounts = body.accounts
  .filter((a) => a && a.platform === 'meta' && a.externalId && a.accessToken)
  .map((a) => ({
    id: a.id,
    externalId: String(a.externalId).startsWith('act_') ? String(a.externalId) : `act_${a.externalId}`,
    name: a.name || String(a.externalId),
    currency: a.currency || null,
    timezone: a.timezone || null,
    accessToken: a.accessToken
  }));
if (accounts.length === 0) return fail(400, 'no Meta ad account with access token in payload');

// Periode pembanding = rentang hari yang sama tepat sebelum periode laporan
const DAY = 86400000;
const toDate = (s) => new Date(`${s}T00:00:00Z`);
const fmt = (d) => d.toISOString().slice(0, 10);
const days = Math.round((toDate(period.end) - toDate(period.start)) / DAY) + 1;
const sD = toDate(period.start);
const eD = toDate(period.end);
const isFullMonths = sD.getUTCDate() === 1 && new Date(eD.getTime() + DAY).getUTCDate() === 1;
let prevStart;
let prevEnd = new Date(sD.getTime() - DAY);
if (isFullMonths) {
  // laporan bulanan → bandingkan dengan bulan kalender sebelumnya (sama seperti WF 3Our "bulan lalu")
  const nMonths = (eD.getUTCFullYear() - sD.getUTCFullYear()) * 12 + (eD.getUTCMonth() - sD.getUTCMonth()) + 1;
  prevStart = new Date(Date.UTC(sD.getUTCFullYear(), sD.getUTCMonth() - nMonths, 1));
} else {
  prevStart = new Date(prevEnd.getTime() - (days - 1) * DAY);
}

// Deck milik user (opsional): harus sudah dibagikan ke akun Google credential Drive (Viewer cukup, karena yang diedit salinannya)
const rawDeck = body.deckId || (body.template.deck && body.template.deck.presentationId) || null;
if (rawDeck !== null && !/^[A-Za-z0-9_-]{20,100}$/.test(String(rawDeck))) return fail(400, 'deckId is invalid');
const deckId = rawDeck ? String(rawDeck) : null;

const template = body.template;
const owner = body.owner || {};
const locale = (owner.locale || template.locale || 'id') === 'en' ? 'en' : 'id';

return [{
  json: {
    ok: true,
    config: { baseDeckId: CONFIG.baseDeckId, reportsFolderId: CONFIG.reportsFolderId, graphVersion: CONFIG.graphVersion, geminiModel: CONFIG.geminiModel },
    requestId: body.requestId,
    reportId: body.reportId || null,
    workspaceId: String(body.workspaceId || 'unknown').replace(/[^A-Za-z0-9_-]/g, ''),
    workspaceName: body.workspaceName || '',
    deckId,
    deckSource: deckId ? 'custom' : 'base',
    callbackUrl: body.callbackUrl,
    template,
    accounts,
    period: { start: period.start, end: period.end, days },
    prevPeriod: { start: fmt(prevStart), end: fmt(prevEnd) },
    compare: body.compare !== false,
    conversionEvent: body.conversionEvent || 'purchase',
    currency: body.currency || template.currency || 'IDR',
    customMetrics: Array.isArray(body.customMetrics) ? body.customMetrics : [],
    recipients: Array.isArray(body.recipients) ? body.recipients.filter((e) => typeof e === 'string' && e.includes('@')) : [],
    owner: { email: owner.email || null, locale },
    locale
  }
}];

// automation/src/ads-fetch-meta.js
// Ambil data Meta Insights ASLI per akun (PRD F5 §3.7 langkah 2).
// - Hanya endpoint yang dipakai template yang dipanggil (hemat kuota API).
// - Token dikirim lewat header Authorization (tidak masuk URL/log).
// - Error per akun → warning; laporan tetap dibuat dari akun lain.
//   Kalau SEMUA akun gagal → throw ADS_SOURCE_UNAVAILABLE (diteruskan ke callback error → refund).
// - Tidak ada data contoh/palsu: kalau data kosong, laporan menampilkan "—".

const job = $input.first().json;
const http = this.helpers.httpRequest.bind(this.helpers);
const GRAPH = `https://graph.facebook.com/${job.config.graphVersion}`;
const pages = job.template.pages || [];
const warnings = [];

// ---------- kebutuhan data dari template ----------
const hasKpi = pages.some((p) => p.type === 'kpi');
const needPrev = job.compare && pages.some((p) => p.type === 'kpi' && p.compare !== false);
const needDaily = pages.some((p) => (p.type === 'trend' && p.granularity !== 'month') || (p.type === 'table' && ['day', 'week'].includes(p.dimension)));
const monthPages = pages.filter((p) => p.type === 'trend' && p.granularity === 'month');
const months = Math.min(24, Math.max(1, ...monthPages.map((p) => Number(p.months) || 6), 1));
const BREAKDOWNS = {
  publisher_platform: 'publisher_platform',
  placement: 'publisher_platform,platform_position',
  age: 'age',
  gender: 'gender',
  age_gender: 'age,gender'
};
const bdDims = [...new Set(pages.filter((p) => p.type === 'breakdown' && BREAKDOWNS[p.dimension]).map((p) => p.dimension))];
const needAdset = pages.some((p) => p.type === 'table' && p.dimension === 'adset');
const needAds = pages.some((p) => p.type === 'creatives' || (p.type === 'table' && p.dimension === 'ad'));

const BASE_FIELDS = 'spend,impressions,reach,clicks,inline_link_clicks,actions,action_values,video_play_actions';
const RESULT_FIELDS = `${BASE_FIELDS},results`;

const range = (s, e) => JSON.stringify({ since: s, until: e });
const monthStart = (() => {
  const d = new Date(`${job.period.start}T00:00:00Z`);
  d.setUTCDate(1);
  d.setUTCMonth(d.getUTCMonth() - (months - 1));
  return d.toISOString().slice(0, 10);
})();

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function graphError(res) {
  const e = (res && res.body && res.body.error) || {};
  return { status: res ? res.statusCode : 0, code: e.code, message: e.message || `HTTP ${res ? res.statusCode : '?'}` };
}

// GET dengan pagination + 1x retry untuk rate limit (kode 4/17/80004) atau 5xx
async function getAll(path, qs, token) {
  const rows = [];
  let url = `${GRAPH}/${path}`;
  let params = { ...qs, limit: qs.limit || 500 };
  for (let page = 0; page < 20 && url; page++) {
    let res;
    for (let attempt = 0; attempt < 2; attempt++) {
      res = await http({
        method: 'GET',
        url,
        qs: params,
        headers: { Authorization: `Bearer ${token}` },
        json: true,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
        timeout: 60000
      });
      const err = graphError(res);
      const retryable = res.statusCode >= 500 || [4, 17, 80004].includes(err.code);
      if (res.statusCode < 400 || !retryable || attempt === 1) break;
      await sleep(3000);
    }
    if (res.statusCode >= 400 || (res.body && res.body.error)) {
      const err = graphError(res);
      const e = new Error(err.message);
      e.graph = err;
      throw e;
    }
    rows.push(...((res.body && res.body.data) || []));
    url = res.body && res.body.paging && res.body.paging.next;
    params = undefined; // URL "next" sudah membawa semua parameter
  }
  return rows;
}

const accountsOut = [];
for (const acc of job.accounts) {
  const tok = acc.accessToken;
  const out = { id: acc.id, externalId: acc.externalId, name: acc.name, currency: acc.currency, ok: true, data: {} };
  const insights = (qs) => getAll(`${acc.externalId}/insights`, qs, tok);
  const cur = range(job.period.start, job.period.end);
  const prev = range(job.prevPeriod.start, job.prevPeriod.end);

  // Permintaan utama: kalau ini gagal (token kedaluwarsa, izin dicabut, akun nonaktif) akun dilewati.
  try {
    const acct = await insights({ level: 'account', fields: `account_name,account_currency,${BASE_FIELDS}`, time_range: cur });
    out.data.account = acct;
    if (acct[0] && acct[0].account_currency) out.currency = acct[0].account_currency;
    if (acct[0] && acct[0].account_name) out.name = acct[0].account_name;
  } catch (e) {
    out.ok = false;
    const g = e.graph || {};
    out.error = { code: g.code || null, message: e.message };
    warnings.push(`account_unavailable:${acc.externalId}:${g.code || 'ERR'}`);
    accountsOut.push(out);
    continue;
  }

  const optional = async (key, qs) => {
    try {
      out.data[key] = await insights(qs);
    } catch (e) {
      out.data[key] = [];
      warnings.push(`fetch_failed:${acc.externalId}:${key}:${(e.graph && e.graph.code) || 'ERR'}`);
    }
  };

  // results hanya akurat di level campaign (sama seperti WF 3Our v3.2)
  await optional('campaigns', { level: 'campaign', fields: `campaign_id,campaign_name,objective,${RESULT_FIELDS}`, time_range: cur });
  if (needPrev) {
    await optional('accountPrev', { level: 'account', fields: BASE_FIELDS, time_range: prev });
    await optional('campaignsPrev', { level: 'campaign', fields: `campaign_id,${RESULT_FIELDS}`, time_range: prev });
  }
  if (needDaily) await optional('daily', { level: 'campaign', fields: `campaign_id,${RESULT_FIELDS}`, time_range: cur, time_increment: 1 });
  if (monthPages.length) await optional('monthly', { level: 'campaign', fields: `campaign_id,${RESULT_FIELDS}`, time_range: range(monthStart, job.period.end), time_increment: 'monthly' });
  for (const dim of bdDims) {
    await optional(`bd_${dim}`, { level: 'campaign', fields: `campaign_id,${RESULT_FIELDS}`, time_range: cur, breakdowns: BREAKDOWNS[dim] });
  }
  if (needAdset) await optional('adsets', { level: 'adset', fields: `adset_id,adset_name,${RESULT_FIELDS}`, time_range: cur });
  if (needAds) await optional('ads', { level: 'ad', fields: `ad_id,ad_name,campaign_name,${RESULT_FIELDS}`, time_range: cur, sort: 'spend_descending' });

  accountsOut.push(out);
}

const okAccounts = accountsOut.filter((a) => a.ok);
if (okAccounts.length === 0) {
  // Tanpa ': ' di pesan — task runner n8n memotong teks sebelum ': ' pada pesan error
  throw new Error(`ADS_SOURCE_UNAVAILABLE - ${accountsOut.map((a) => `${a.externalId} (${String(a.error && a.error.message).replace(/:\s*/g, ' - ')})`).join('; ')}`);
}

// Kurs: hanya kalau mata uang akun berbeda dari mata uang laporan
let fx = null;
const reportCur = String(job.currency || 'IDR').toUpperCase();
const foreign = [...new Set(okAccounts.map((a) => String(a.currency || reportCur).toUpperCase()).filter((c) => c !== reportCur))];
if (foreign.length) {
  try {
    const res = await http({ method: 'GET', url: `https://open.er-api.com/v6/latest/${reportCur}`, json: true, timeout: 20000 });
    if (res && res.result === 'success' && res.rates) {
      fx = { base: reportCur, source: 'open.er-api.com', date: res.time_last_update_utc || null, rates: {} };
      for (const c of foreign) {
        if (res.rates[c]) fx.rates[c] = res.rates[c];
        else warnings.push(`fx_missing:${c}`);
      }
    } else {
      warnings.push('fx_unavailable');
    }
  } catch (e) {
    warnings.push('fx_unavailable');
  }
}

return [{
  json: {
    requestId: job.requestId,
    fetched: { accounts: accountsOut.map(({ ok, error, ...rest }) => ({ ok, error: error || null, ...rest })), fx, monthStart, months },
    warnings
  }
}];

// automation/src/ads-process-metrics.js
// Normalisasi data Meta → hitung metrics (modul SSOT shared/ads-metrics.js, di-inline saat build)
// → susun model per halaman template (teks, KPI, tabel, data grafik, creative) + prompt AI.
// PRD F5 §3.2, §3.3, §3.7 langkah 2/2a.

// ==== shared/ads-metrics.js (di-inline oleh build-workflows.mjs) ====
// backend/shared/ads-metrics.js
// Pustaka metrics iklan (Meta Ads & rancangan Google Ads).
// Modul JS murni, tanpa dependensi eksternal, digunakan oleh backend, frontend, dan n8n.

const BASE_METRICS = {
  spend: {
    id: 'spend',
    unit: 'currency',
    agg: 'sum',
    sources: { meta: 'spend', google: 'metrics.cost_micros / 1e6' },
    labels: { en: 'Amount Spent', id: 'Biaya Iklan' }
  },
  impressions: {
    id: 'impressions',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'impressions', google: 'metrics.impressions' },
    labels: { en: 'Impressions', id: 'Impresi' }
  },
  reach: {
    id: 'reach',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'reach', google: null },
    labels: { en: 'Reach', id: 'Jangkauan' }
  },
  clicks: {
    id: 'clicks',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'clicks', google: 'metrics.clicks' },
    labels: { en: 'Clicks (All)', id: 'Klik (Semua)' }
  },
  link_clicks: {
    id: 'link_clicks',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'inline_link_clicks', google: 'metrics.clicks' },
    labels: { en: 'Link Clicks', id: 'Klik Tautan' }
  },
  conversions: {
    id: 'conversions',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'actions', google: 'metrics.conversions' },
    labels: { en: 'Conversions', id: 'Konversi' }
  },
  conversion_value: {
    id: 'conversion_value',
    unit: 'currency',
    agg: 'sum',
    sources: { meta: 'action_values', google: 'metrics.conversions_value' },
    labels: { en: 'Conversion Value', id: 'Nilai Konversi' }
  },
  leads: {
    id: 'leads',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'actions.lead', google: null },
    labels: { en: 'Leads', id: 'Prospek (Leads)' }
  },
  purchases: {
    id: 'purchases',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'actions.purchase', google: null },
    labels: { en: 'Purchases', id: 'Pembelian' }
  },
  video_views: {
    id: 'video_views',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'video_play_actions', google: 'metrics.video_views' },
    labels: { en: 'Video Views', id: 'Penayangan Video' }
  },
  results: {
    id: 'results',
    unit: 'number',
    agg: 'sum',
    sources: { meta: 'results', google: 'metrics.conversions' },
    labels: { en: 'Results', id: 'Hasil' }
  },
  purchase_value: {
    id: 'purchase_value',
    unit: 'currency',
    agg: 'sum',
    sources: { meta: 'action_values.purchase', google: null },
    labels: { en: 'Purchase Value', id: 'Nilai Pembelian' }
  }
};

const DERIVED_METRICS = {
  cost_per_result: {
    id: 'cost_per_result',
    unit: 'currency',
    formula: 'spend / results',
    calculate: (m) => safeDivide(m.spend, m.results),
    labels: { en: 'Cost per Result', id: 'Biaya per Hasil' }
  },
  cost_per_purchase: {
    id: 'cost_per_purchase',
    unit: 'currency',
    formula: 'spend / purchases',
    calculate: (m) => safeDivide(m.spend, m.purchases),
    labels: { en: 'Cost per Purchase', id: 'Biaya per Pembelian' }
  },
  ctr: {
    id: 'ctr',
    unit: 'percent',
    formula: 'clicks / impressions',
    calculate: (m) => safeDivide(m.clicks, m.impressions),
    labels: { en: 'CTR (All)', id: 'CTR' }
  },
  cpc: {
    id: 'cpc',
    unit: 'currency',
    formula: 'spend / clicks',
    calculate: (m) => safeDivide(m.spend, m.clicks),
    labels: { en: 'CPC (All)', id: 'CPC' }
  },
  cpm: {
    id: 'cpm',
    unit: 'currency',
    formula: '(spend / impressions) * 1000',
    calculate: (m) => {
      const res = safeDivide(m.spend, m.impressions);
      return res !== null ? res * 1000 : null;
    },
    labels: { en: 'CPM', id: 'CPM' }
  },
  cpa: {
    id: 'cpa',
    unit: 'currency',
    formula: 'spend / conversions',
    calculate: (m) => safeDivide(m.spend, m.conversions),
    labels: { en: 'CPA', id: 'CPA (Biaya per Konversi)' }
  },
  roas: {
    id: 'roas',
    unit: 'ratio',
    formula: 'conversion_value / spend',
    calculate: (m) => safeDivide(m.conversion_value, m.spend),
    labels: { en: 'ROAS', id: 'ROAS' }
  },
  frequency: {
    id: 'frequency',
    unit: 'ratio',
    platform: 'meta',
    formula: 'impressions / reach',
    calculate: (m) => (m.reach ? safeDivide(m.impressions, m.reach) : null),
    labels: { en: 'Frequency', id: 'Frekuensi' }
  },
  conv_rate: {
    id: 'conv_rate',
    unit: 'percent',
    formula: 'conversions / clicks',
    calculate: (m) => safeDivide(m.conversions, m.clicks),
    labels: { en: 'Conversion Rate', id: 'Tingkat Konversi' }
  }
};

const ALL_METRICS = { ...BASE_METRICS, ...DERIVED_METRICS };

function isKnownMetric(id) {
  return Boolean(ALL_METRICS[id]);
}

function safeDivide(numerator, denominator) {
  if (numerator === null || numerator === undefined || denominator === null || denominator === undefined) {
    return null;
  }
  const num = Number(numerator);
  const den = Number(denominator);
  if (isNaN(num) || isNaN(den) || den === 0) {
    return null;
  }
  return num / den;
}

/**
 * Agregasi baris data mentah ke metrics terhitung.
 * Menghitung base metrics dari SUM baris, lalu menghitung derived metrics dari SUM tersebut
 * (bukan rata-rata rasio per baris).
 */
function aggregateRows(rows = [], { customMetrics = [] } = {}) {
  const sums = {};
  for (const key of Object.keys(BASE_METRICS)) {
    sums[key] = 0;
  }

  let rowCount = 0;
  for (const row of rows) {
    if (!row) continue;
    rowCount++;
    for (const key of Object.keys(BASE_METRICS)) {
      const val = row[key];
      if (val !== null && val !== undefined && !isNaN(Number(val))) {
        sums[key] += Number(val);
      }
    }
  }

  // Jika tidak ada data sama sekali
  const result = {};
  for (const key of Object.keys(BASE_METRICS)) {
    result[key] = rowCount > 0 ? sums[key] : null;
  }

  // Hitung derived metrics dari jumlah agregat
  for (const [key, def] of Object.entries(DERIVED_METRICS)) {
    result[key] = def.calculate(result);
  }

  // Hitung custom metrics jika ada
  if (Array.isArray(customMetrics)) {
    for (const cm of customMetrics) {
      if (!cm || !cm.id || !cm.formula) continue;
      const customKey = cm.id.startsWith('custom:') ? cm.id : `custom:${cm.id}`;
      try {
        result[customKey] = evaluateFormula(cm.formula, result);
      } catch {
        result[customKey] = null;
      }
    }
  }

  return result;
}

// =====================================================================
// FORMULA PARSER & EVALUATOR (Shunting-Yard, tanpa eval / new Function)
// =====================================================================

const TOKEN_TYPES = {
  NUMBER: 'NUMBER',
  IDENTIFIER: 'IDENTIFIER',
  OPERATOR: 'OPERATOR',
  LPAREN: 'LPAREN',
  RPAREN: 'RPAREN'
};

const OPERATORS = {
  '+': { precedence: 1, assoc: 'L', fn: (a, b) => a + b },
  '-': { precedence: 1, assoc: 'L', fn: (a, b) => a - b },
  '*': { precedence: 2, assoc: 'L', fn: (a, b) => a * b },
  '/': { precedence: 2, assoc: 'L', fn: (a, b) => safeDivide(a, b) }
};

/**
 * Tokenize string formula
 */
function tokenizeFormula(formula) {
  if (typeof formula !== 'string') {
    throw { message: 'Formula must be a string', position: 0 };
  }
  if (formula.length > 200) {
    throw { message: 'Formula exceeds maximum length of 200 characters', position: 200 };
  }

  const tokens = [];
  let i = 0;

  while (i < formula.length) {
    const ch = formula[i];

    if (/\s/.test(ch)) {
      i++;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: TOKEN_TYPES.LPAREN, value: '(', position: i });
      i++;
      continue;
    }

    if (ch === ')') {
      tokens.push({ type: TOKEN_TYPES.RPAREN, value: ')', position: i });
      i++;
      continue;
    }

    if (ch in OPERATORS) {
      // Penanganan unari minus: jika '-' berada di awal atau setelah '(' atau operator lain
      const prev = tokens[tokens.length - 1];
      if (ch === '-' && (!prev || prev.type === TOKEN_TYPES.LPAREN || prev.type === TOKEN_TYPES.OPERATOR)) {
        // Anggap sebagai 0 - x dengan menyisipkan token 0 dan minus
        tokens.push({ type: TOKEN_TYPES.NUMBER, value: 0, position: i });
      }
      tokens.push({ type: TOKEN_TYPES.OPERATOR, value: ch, position: i });
      i++;
      continue;
    }

    // Number literal (integer atau float)
    if (/[0-9]/.test(ch) || (ch === '.' && /[0-9]/.test(formula[i + 1] || ''))) {
      const start = i;
      let numStr = '';
      let hasDot = false;
      while (i < formula.length) {
        const c = formula[i];
        if (/[0-9]/.test(c)) {
          numStr += c;
          i++;
        } else if (c === '.' && !hasDot) {
          hasDot = true;
          numStr += c;
          i++;
        } else {
          break;
        }
      }
      tokens.push({ type: TOKEN_TYPES.NUMBER, value: parseFloat(numStr), position: start });
      continue;
    }

    // Identifier (nama metric dasar atau turunan)
    if (/[a-zA-Z_]/.test(ch)) {
      const start = i;
      let ident = '';
      while (i < formula.length && /[a-zA-Z0-9_]/.test(formula[i])) {
        ident += formula[i];
        i++;
      }

      // Tolak referensi custom: lain untuk mencegah siklus
      if (ident.toLowerCase().startsWith('custom')) {
        throw { message: 'Custom metrics cannot reference other custom metrics', position: start };
      }

      tokens.push({ type: TOKEN_TYPES.IDENTIFIER, value: ident, position: start });
      continue;
    }

    // Karakter ilegal (misal: ;, &, $, dsb)
    throw { message: `Unexpected character: '${ch}'`, position: i };
  }

  return tokens;
}

/**
 * Validasi sintaks formula dan identifier yang dipakai.
 */
function validateFormula(formula) {
  if (!formula || typeof formula !== 'string' || !formula.trim()) {
    return { valid: false, error: 'Formula cannot be empty', position: 0 };
  }
  if (formula.length > 200) {
    return { valid: false, error: 'Formula exceeds maximum length of 200 characters', position: 200 };
  }

  let tokens;
  try {
    tokens = tokenizeFormula(formula);
  } catch (err) {
    return { valid: false, error: err.message, position: err.position };
  }

  if (tokens.length === 0) {
    return { valid: false, error: 'Formula contains no tokens', position: 0 };
  }

  // Validasi identifier adalah metric dasar / turunan yang valid
  for (const t of tokens) {
    if (t.type === TOKEN_TYPES.IDENTIFIER) {
      if (!isKnownMetric(t.value)) {
        return {
          valid: false,
          error: `Unknown metric '${t.value}' in formula`,
          position: t.position
        };
      }
    }
  }

  // Validasi grammar Shunting-Yard
  try {
    const rpn = parseToRPN(tokens);
    if (rpn.length === 0) {
      return { valid: false, error: 'Empty expression', position: 0 };
    }
  } catch (err) {
    return { valid: false, error: err.message, position: err.position };
  }

  return { valid: true };
}

/**
 * Konversi daftar token ke Reverse Polish Notation (RPN) via Shunting-Yard
 */
function parseToRPN(tokens) {
  const outputQueue = [];
  const operatorStack = [];
  let expectOperand = true;

  for (let idx = 0; idx < tokens.length; idx++) {
    const token = tokens[idx];

    if (token.type === TOKEN_TYPES.NUMBER || token.type === TOKEN_TYPES.IDENTIFIER) {
      if (!expectOperand) {
        throw { message: `Unexpected operand '${token.value}'`, position: token.position };
      }
      outputQueue.push(token);
      expectOperand = false;
    } else if (token.type === TOKEN_TYPES.OPERATOR) {
      if (expectOperand) {
        throw { message: `Unexpected operator '${token.value}'`, position: token.position };
      }
      const op1 = token.value;
      const o1 = OPERATORS[op1];

      while (operatorStack.length > 0) {
        const top = operatorStack[operatorStack.length - 1];
        if (top.type === TOKEN_TYPES.OPERATOR) {
          const o2 = OPERATORS[top.value];
          if ((o1.assoc === 'L' && o1.precedence <= o2.precedence) ||
              (o1.assoc === 'R' && o1.precedence < o2.precedence)) {
            outputQueue.push(operatorStack.pop());
            continue;
          }
        }
        break;
      }
      operatorStack.push(token);
      expectOperand = true;
    } else if (token.type === TOKEN_TYPES.LPAREN) {
      operatorStack.push(token);
      expectOperand = true;
    } else if (token.type === TOKEN_TYPES.RPAREN) {
      if (expectOperand) {
        throw { message: "Unexpected ')' before operand", position: token.position };
      }
      let foundMatching = false;
      while (operatorStack.length > 0) {
        const top = operatorStack.pop();
        if (top.type === TOKEN_TYPES.LPAREN) {
          foundMatching = true;
          break;
        }
        outputQueue.push(top);
      }
      if (!foundMatching) {
        throw { message: 'Mismatched parentheses: missing opening bracket', position: token.position };
      }
      expectOperand = false;
    }
  }

  if (expectOperand) {
    const lastPos = tokens.length > 0 ? tokens[tokens.length - 1].position + 1 : 0;
    throw { message: 'Formula ends prematurely with dangling operator or empty bracket', position: lastPos };
  }

  while (operatorStack.length > 0) {
    const top = operatorStack.pop();
    if (top.type === TOKEN_TYPES.LPAREN || top.type === TOKEN_TYPES.RPAREN) {
      throw { message: 'Mismatched parentheses: unclosed bracket', position: top.position };
    }
    outputQueue.push(top);
  }

  return outputQueue;
}

/**
 * Evaluasi formula dengan nilai metric yang diberikan.
 * Mengembalikan number atau null (misal pembagian dengan nol atau nilai metric null).
 */
function evaluateFormula(formula, metricValues = {}) {
  const validation = validateFormula(formula);
  if (!validation.valid) {
    throw new Error(`Invalid formula: ${validation.error} at position ${validation.position}`);
  }

  const tokens = tokenizeFormula(formula);
  const rpn = parseToRPN(tokens);
  const evalStack = [];

  for (const token of rpn) {
    if (token.type === TOKEN_TYPES.NUMBER) {
      evalStack.push(token.value);
    } else if (token.type === TOKEN_TYPES.IDENTIFIER) {
      const rawVal = metricValues[token.value];
      if (rawVal === null || rawVal === undefined) {
        return null;
      }
      const val = Number(rawVal);
      if (isNaN(val)) return null;
      evalStack.push(val);
    } else if (token.type === TOKEN_TYPES.OPERATOR) {
      if (evalStack.length < 2) {
        return null;
      }
      const b = evalStack.pop();
      const a = evalStack.pop();
      if (a === null || b === null) return null;

      const opDef = OPERATORS[token.value];
      const res = opDef.fn(a, b);
      if (res === null || isNaN(res)) {
        return null;
      }
      evalStack.push(res);
    }
  }

  if (evalStack.length !== 1) {
    return null;
  }
  const finalVal = evalStack[0];
  return finalVal === null || isNaN(finalVal) ? null : finalVal;
}

