      groups = groupBy(rowsOf('daily'), (r) => r.date_start, (r) => dayLabel(r.date_start)).sort((a, b) => (a.key < b.key ? -1 : 1));
    }
    page.chart = { kind: p.chart || (p.granularity === 'month' ? 'combo' : 'bar'), header: ['', ...ids.map(chartLabel)], rows: groups.map((g) => [g.name, ...ids.map((id) => chartVal(id, g.m[id]))]) };
    if (!groups.length) warnings.push(`no_data:page${i}:trend`);
  } else if (p.type === 'breakdown') {
    const ids = (p.metrics || ['spend']).slice(0, 2);
    const groups = sortRows(breakdownGroups(p.dimension), `-${ids[0]}`).slice(0, 12);
    page.chart = { kind: p.chart || 'bar', header: ['', ...ids.map(chartLabel)], rows: groups.map((g) => [g.name, ...ids.map((id) => chartVal(id, g.m[id]))]) };
    page.summary = groups.slice(0, 6).map((g) => `${g.name}: ${ids.map((id) => `${label(id)} ${fmt(id, g.m[id])}`).join(', ')}`).join('; ');
    if (!groups.length) warnings.push(`no_data:page${i}:breakdown`);
    if (groups.length) aiFacts.push(`${page.title} — ${page.summary}`);
    if (p.insight) aiTasks.push({ key: `p${i}`, kind: 'short', title: page.title, facts: page.summary });
  } else if (p.type === 'table') {
    const ids = (p.metrics || []).slice(0, 8);
    const limit = Math.min(25, Number(p.limit) || 10);
    const groups = sortRows(tableGroups(p.dimension), p.sort, '-spend').slice(0, limit);
    page.table = {
      header: [(DIM_LABEL[p.dimension] || [p.dimension, p.dimension])[locale === 'en' ? 1 : 0], ...ids.map(label)],
      rows: groups.map((g) => [String(g.name || '—'), ...ids.map((id) => fmt(id, g.m[id]))]),
      empty: L('Tidak ada data pada periode ini', 'No data for this period')
    };
  } else if (p.type === 'creatives') {
    const ids = (p.metrics || ['spend', 'results', 'cost_per_result']).slice(0, 4);
    const limit = Math.min(9, Number(p.limit) || 3);
    let list = adGroups.filter((g) => g.m.spend > 0 && !usedAds.has(g.key));
    if (p.variant === 'lowest') {
      // biaya per hasil tertinggi; iklan ber-spend tanpa hasil dianggap paling perlu dievaluasi
      list = [...list].sort((a, b) => {
        const ca = a.m.cost_per_result === null ? Infinity : a.m.cost_per_result;
        const cb = b.m.cost_per_result === null ? Infinity : b.m.cost_per_result;
        return cb === ca ? b.m.spend - a.m.spend : cb - ca;
      });
    } else {
      list = sortRows(list, p.sort, '-results');
    }
    list = list.slice(0, limit);
    page.creatives = [];
    for (const g of list) {
      usedAds.add(g.key);
      const imageUrl = await creativeImage(g.key);
      if (!imageUrl) warnings.push(`creative_image_missing:${g.key}`);
      page.creatives.push({ adId: g.key, name: g.name, imageUrl, metrics: ids.map((id) => `${label(id)}: ${fmt(id, g.m[id])}`).join('\n') });
    }
  } else if (p.type === 'ai_insight') {
    aiTasks.push({ key: `p${i}`, kind: 'long', title: page.title, focus: p.focus || '' });
  } else if (p.type === 'custom_text') {
    page.text = applyPh(p.text || '');
  } else if (p.type === 'custom_image') {
    page.imageUrl = p.imageUrl || null;
    page.caption = applyPh(p.caption || '');
    if (!page.imageUrl) warnings.push(`custom_image_missing:page${i}`);
  }
  if (page.chart) charts.push({ pageIndex: i, ...page.chart });
  model.push(page);
}

// ---------------- prompt AI (satu panggilan Gemini untuk semua halaman) ----------------
let aiPrompt = null;
if (aiTasks.length) {
  const lang = L('Bahasa Indonesia yang profesional dan mudah dipahami pemilik bisnis', 'clear professional English for business owners');
  aiPrompt = [
    L('Kamu adalah Senior Performance Marketing Analyst. Gunakan HANYA data berikut, jangan mengarang angka.', 'You are a Senior Performance Marketing Analyst. Use ONLY the data below; never invent numbers.'),
    '',
    'DATA:',
    ...aiFacts,
    '',
    L('TUGAS (tulis dalam', 'TASKS (write in') + ` ${lang}):`,
    ...aiTasks.map((t) => t.kind === 'long'
      ? `- "${t.key}": ${L('ringkasan eksekutif + 3–5 rekomendasi konkret bulan depan, maksimal 180 kata', 'executive summary + 3–5 concrete recommendations for next month, max 180 words')}${t.focus ? ` (${L('fokus', 'focus')}: ${t.focus})` : ''}. ${L('Judul halaman', 'Page title')}: ${t.title}`
      : `- "${t.key}": ${L('1–2 kalimat insight untuk grafik', '1–2 sentence insight for the chart')} "${t.title}" (${t.facts})`),
    '',
    L('Balas HANYA JSON objek dengan key persis seperti di atas, nilai berupa teks biasa (boleh baris baru dan "• "), tanpa markdown.', 'Reply with ONLY a JSON object using exactly the keys above; values are plain text (newlines and "• " allowed), no markdown.')
  ].join('\n');
}

return [{
  json: {
    requestId: job.requestId,
    period: PERIOD,
    fileName: `${L('Laporan Iklan', 'Ads Report')} – ${PERIOD} – ${ACCOUNT_NAMES}`.slice(0, 150) + ` – ${String(job.requestId).slice(-6)}`,
    model,
    charts,
    ai: { needed: aiTasks.length > 0, prompt: aiPrompt, keys: aiTasks.map((t) => t.key) },
    summary: {
      period: { start: job.period.start, end: job.period.end, label: PERIOD },
      currency: reportCur,
      accounts: okAccounts.map((a) => ({ id: a.externalId, name: a.name })),
      totals: Object.fromEntries(['spend', 'impressions', 'reach', 'clicks', 'ctr', 'cpc', 'results', 'cost_per_result', 'conversions', 'conversion_value', 'roas'].map((k) => [k, totals[k] === undefined ? null : totals[k]])),
      previous: prevTotals ? Object.fromEntries(['spend', 'impressions', 'reach', 'clicks', 'results'].map((k) => [k, prevTotals[k]])) : null,
      fx: fetched.fx ? { source: fetched.fx.source, date: fetched.fx.date, rates: fetched.fx.rates } : null
    },
    warnings
  }
}];

// automation/src/ads-parse-insight.js
// Gabungkan hasil Gemini (satu panggilan untuk semua halaman AI) ke model halaman.
// Kalau Gemini gagal/kosong, laporan TETAP dibuat dengan teks cadangan + warning ai_unavailable.

const proc = $('Proses Metrik').first().json;
const job = $('Auth & Normalize (Ads)').first().json;
const warnings = [...(proc.warnings || [])];
const L = (id, en) => (job.locale === 'en' ? en : id);

let insights = {};
let aiUsed = 0;
if (proc.ai && proc.ai.needed) {
  const res = $input.first().json || {};
  try {
    const text = res.candidates && res.candidates[0] && res.candidates[0].content && res.candidates[0].content.parts
      ? res.candidates[0].content.parts.map((p) => p.text || '').join('')
      : '';
    const cleaned = text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    const parsed = cleaned ? JSON.parse(cleaned) : {};
    if (parsed && typeof parsed === 'object') insights = parsed;
  } catch (e) {
    insights = {};
  }
  if (!Object.keys(insights).length) warnings.push('ai_unavailable');
}

const clean = (s, max) => String(s || '').replace(/\*\*/g, '').replace(/^#+\s*/gm, '').trim().slice(0, max);
const model = proc.model.map((page) => {
  const key = `p${page.index}`;
  if (page.type === 'ai_insight') {
    const t = clean(insights[key], 1600);
    if (t) aiUsed++;
    return { ...page, insight: t || L('Insight AI tidak tersedia untuk laporan ini. Silakan buat ulang laporan untuk mencoba lagi.', 'AI insight is not available for this report. Please regenerate the report to try again.') };
  }
  if (page.type === 'breakdown') {
    return { ...page, insight: clean(insights[key], 400) };
  }
  return page;
});

return [{ json: { ...proc, model, warnings, aiPages: aiUsed } }];

// automation/src/ads-sheet-requests.js
// Susun Google Sheets batchUpdate: satu tab data per grafik + chart (ID deterministik 1000+k)
// supaya bisa langsung di-link ke Slides tanpa membaca respons (PRD F5 §3.7 2a, "linked Sheets chart").

const proc = $('Parse Insight').first().json;
const job = $('Auth & Normalize (Ads)').first().json;
const spreadsheetId = $input.first().json.id;
if (!spreadsheetId) throw new Error('ADS_REPORT_FAILED - spreadsheet data tidak terbuat');

const L = (id, en) => (job.locale === 'en' ? en : id);
const requests = [{ updateSpreadsheetProperties: { properties: { title: `Data – ${proc.period}` }, fields: 'title' } }];
const chartMap = {};

proc.charts.forEach((c, k) => {
  const sheetId = 100 + k;
  const chartId = 1000 + k;
  const header = [c.header[0] || L('Kategori', 'Category'), ...c.header.slice(1)];
  const rows = c.rows.length ? c.rows : [['—', ...header.slice(1).map(() => 0)]];
  const nCols = header.length;
  const cell = (v) => (typeof v === 'number' ? { userEnteredValue: { numberValue: v } } : { userEnteredValue: { stringValue: String(v) } });
  requests.push({ addSheet: { properties: { sheetId, title: `p${c.pageIndex + 1}`, gridProperties: { rowCount: Math.max(rows.length + 5, 20), columnCount: nCols + 12 } } } });
  requests.push({ updateCells: { start: { sheetId, rowIndex: 0, columnIndex: 0 }, rows: [header, ...rows].map((r) => ({ values: r.map(cell) })), fields: 'userEnteredValue' } });

  const src = (col) => ({ sourceRange: { sources: [{ sheetId, startRowIndex: 0, endRowIndex: rows.length + 1, startColumnIndex: col, endColumnIndex: col + 1 }] } });
  let spec;
  if (c.kind === 'pie') {
    spec = { pieChart: { legendPosition: 'RIGHT_LEGEND', domain: src(0), series: src(1), pieHole: 0.45 } };
  } else {
    const type = c.kind === 'line' ? 'LINE' : c.kind === 'combo' ? 'COMBO' : 'COLUMN';
    spec = {
      basicChart: {
        chartType: type,
        legendPosition: 'BOTTOM_LEGEND',
        headerCount: 1,
        axis: [{ position: 'BOTTOM_AXIS' }, { position: 'LEFT_AXIS' }],
        domains: [{ domain: src(0) }],
        series: header.slice(1).map((_, j) => ({
          series: src(j + 1),
          targetAxis: j === 0 ? 'LEFT_AXIS' : 'RIGHT_AXIS',
          ...(type === 'COMBO' ? { type: j === 0 ? 'COLUMN' : 'LINE' } : {})
        }))
      }
    };
  }
  requests.push({ addChart: { chart: { chartId, spec, position: { overlayPosition: { anchorCell: { sheetId, rowIndex: 0, columnIndex: nCols + 1 } } } } } });
  chartMap[c.pageIndex] = chartId;
});

return [{ json: { spreadsheetId, requests, chartMap } }];

// automation/src/ads-render-slides.js
// Susun Slides batchUpdate untuk deck salinan base deck (PRD F5 §3.7 langkah 2, 2a).
// Base deck: 1 slide layout per jenis halaman, ditandai di SPEAKER NOTES dengan "layout:<type>".
// Elemen dikenali lewat alt text (description) atau placeholder teks {{...}} — bukan posisi.
// Detail konvensi: automation/ADS-BASE-DECK.md.
//
// Urutan request: duplikat layout per halaman (ID objek deterministik) → isi teks/tabel/grafik
// → urutkan slide → hapus semua slide asli base deck. Gambar creative dikirim TERPISAH
// (node "Susun Request Gambar") supaya satu URL gambar yang gagal tidak menggagalkan laporan.

const pres = $input.first().json;
const proc = $('Parse Insight').first().json;
const job = $('Auth & Normalize (Ads)').first().json;
const sheet = $('Susun Data Grafik').first().json;
const warnings = [];

if (!pres || !Array.isArray(pres.slides)) throw new Error('ADS_REPORT_FAILED - base deck tidak bisa dibaca');

// ---------- util ----------
const textOf = (te) => (Array.isArray(te) ? te.map((t) => (t.textRun ? t.textRun.content : '')).join('') : '');
function walk(elements, fn) {
  for (const el of elements || []) {
    fn(el);
    if (el.elementGroup) walk(el.elementGroup.children, fn);
  }
}
function slideTexts(slide) {
  const out = [];
  walk(slide.pageElements, (el) => {
    if (el.shape && el.shape.text) out.push(textOf(el.shape.text.textElements));
    if (el.table) for (const r of el.table.tableRows || []) for (const c of r.tableCells || []) if (c.text) out.push(textOf(c.text.textElements));
  });
  return out.join('\n');
}
function notesText(slide) {
  const np = slide.slideProperties && slide.slideProperties.notesPage;
  if (!np) return '';
  const parts = [];
  walk(np.pageElements, (el) => {
    if (el.shape && el.shape.text) parts.push(textOf(el.shape.text.textElements));
  });
  return parts.join('\n');
}
const role = (el) => String(el.description || '').trim().toLowerCase();
const toEmu = (d) => (!d ? 0 : d.unit === 'PT' ? d.magnitude * 12700 : d.magnitude || 0);
function boxOf(el) {
  const t = el.transform || {};
  const k = t.unit === 'PT' ? 12700 : 1;
  return {
    x: Math.round((t.translateX || 0) * k),
    y: Math.round((t.translateY || 0) * k),
    w: Math.round(toEmu(el.size && el.size.width) * (t.scaleX || 1)),
    h: Math.round(toEmu(el.size && el.size.height) * (t.scaleY || 1))
  };
}

// ---------- peta layout ----------
const layouts = {};
for (const s of pres.slides) {
  const m = notesText(s).match(/layout\s*:\s*([a-z_]+)/i);
  if (m && !layouts[m[1].toLowerCase()]) layouts[m[1].toLowerCase()] = s;
}
if (!Object.keys(layouts).length) throw new Error('ADS_REPORT_FAILED - base deck tidak punya slide layout (speaker notes "layout:<type>")');

const common = {
  period: proc.period,
  account_name: (proc.summary.accounts || []).map((a) => a.name).join(', '),
  workspace_name: job.workspaceName || '',
  client_name: job.workspaceName || '',
  ads_platform: 'Meta Ads'
};

const requests = [];
const contentReqs = [];
const imageJobs = [];
const newSlideIds = [];

proc.model.forEach((page, pi) => {
  const layout = layouts[page.type];
  if (!layout) {
    warnings.push(`layout_missing:${page.type}`);
    return;
  }
  const P = `mk${String(pi).padStart(2, '0')}`;
  const slideId = `${P}slide`;
  const idMap = { [layout.objectId]: slideId };
  let seq = 0;
  walk(layout.pageElements, (el) => {
    idMap[el.objectId] = `${P}e${++seq}`;
  });
  requests.push({ duplicateObject: { objectId: layout.objectId, objectIds: idMap } });
  newSlideIds.push(slideId);
  const nid = (el) => idMap[el.objectId];

  // ---- nilai placeholder teks ----
  const values = { ...common, title: page.title || '', subtitle: page.subtitle || '', insight: page.insight || '', text: page.text || '', caption: page.caption || '' };
  (page.kpis || []).forEach((k, i) => {
    values[`kpi${i + 1}_label`] = k.label;
    values[`kpi${i + 1}_value`] = k.value;
    values[`kpi${i + 1}_delta`] = k.delta;
  });
  (page.creatives || []).forEach((c, i) => {
    values[`c${i + 1}_name`] = c.name;
    values[`c${i + 1}_metrics`] = c.metrics;
  });
  const found = new Set();
  const re = /\{\{\s*([a-z0-9_]+)\s*\}\}/gi;
  let m;
  const txt = slideTexts(layout);
  while ((m = re.exec(txt))) found.add(m[0]);
  for (const token of found) {
    const key = token.replace(/[{}\s]/g, '').toLowerCase();
    // slot KPI/creative yang tidak terpakai → kosong; placeholder tak dikenal → kosong + warning
    const known = key in values || /^kpi\d+_(label|value|delta)$/.test(key) || /^c\d+_(name|metrics)$/.test(key);
    if (!known) warnings.push(`unknown_placeholder:${page.type}:${key}`);
    contentReqs.push({ replaceAllText: { containsText: { text: token, matchCase: true }, replaceText: String(values[key] ?? ''), pageObjectIds: [slideId] } });
  }

  // ---- elemen berdasarkan alt text ----
  let chartSeq = 0;
  const nKpi = (page.kpis || []).length;
  const nCre = (page.creatives || []).length;
  walk(layout.pageElements, (el) => {
    const r = role(el);
    if (!r) return;
    let mm;
    if ((mm = r.match(/^kpi (\d+)$/)) && Number(mm[1]) > nKpi) {
      contentReqs.push({ deleteObject: { objectId: nid(el) } });
    } else if ((mm = r.match(/^creative (\d+)( img)?$/))) {
      const n = Number(mm[1]);
      if (n > nCre) contentReqs.push({ deleteObject: { objectId: nid(el) } });
      else if (mm[2] && el.image) {
        const c = page.creatives[n - 1];
        if (c.imageUrl) imageJobs.push({ replaceImage: { imageObjectId: nid(el), url: c.imageUrl, imageReplaceMethod: 'CENTER_CROP' }, ref: `creative:${c.adId}` });
      }
    } else if (r === 'custom image' && el.image && page.imageUrl) {
      imageJobs.push({ replaceImage: { imageObjectId: nid(el), url: page.imageUrl, imageReplaceMethod: 'CENTER_INSIDE' }, ref: `custom_image:page${pi}` });
    } else if (r === 'chart') {
      const chartId = sheet.chartMap[String(page.index)];
      if (chartId === undefined) {
        warnings.push(`chart_without_data:page${pi}`);
        return;
      }
      const b = boxOf(el);
      contentReqs.push({
        createSheetsChart: {
          objectId: `${P}ch${++chartSeq}`,
          spreadsheetId: sheet.spreadsheetId,
          chartId,
          linkingMode: 'LINKED',
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: b.w, unit: 'EMU' }, height: { magnitude: b.h, unit: 'EMU' } },
            transform: { scaleX: 1, scaleY: 1, shearX: 0, shearY: 0, translateX: b.x, translateY: b.y, unit: 'EMU' }
          }
        }
      });
      contentReqs.push({ deleteObject: { objectId: nid(el) } });
    } else if (r === 'table' && el.table && page.table) {
      const tid = nid(el);
      const t = page.table;
      const R = el.table.rows;
      const C = el.table.columns;
      const header = t.header.slice(0, C);
      if (t.header.length > C) warnings.push(`table_columns_truncated:page${pi}:${t.header.length}>${C}`);
      const n = header.length;
      const data = t.rows.length ? t.rows.map((row) => row.slice(0, n)) : [[t.empty, ...header.slice(1).map(() => '–')]];
      const cellHasText = (ri, ci) => {
        const row = el.table.tableRows[ri];
        const cell = row && row.tableCells[ci];
        return Boolean(cell && cell.text && textOf(cell.text.textElements).replace(/\n/g, '').length);
      };
      // kolom berlebih (dari kanan)
      for (let c = C - 1; c >= n; c--) contentReqs.push({ deleteTableColumn: { tableObjectId: tid, cellLocation: { rowIndex: 0, columnIndex: c } } });
      // baris data: tambah / hapus
      const have = R - 1;
      if (data.length > have) contentReqs.push({ insertTableRows: { tableObjectId: tid, cellLocation: { rowIndex: R - 1, columnIndex: 0 }, insertBelow: true, number: data.length - have } });
      for (let r2 = have; r2 > data.length; r2--) contentReqs.push({ deleteTableRow: { tableObjectId: tid, cellLocation: { rowIndex: r2, columnIndex: 0 } } });
      const put = (ri, ci, text) => {
        if (ri < R && ci < C && cellHasText(ri, ci)) contentReqs.push({ deleteText: { objectId: tid, cellLocation: { rowIndex: ri, columnIndex: ci }, textRange: { type: 'ALL' } } });
        if (String(text).length) contentReqs.push({ insertText: { objectId: tid, cellLocation: { rowIndex: ri, columnIndex: ci }, text: String(text), insertionIndex: 0 } });
      };
      header.forEach((h, ci) => put(0, ci, h));
      data.forEach((row, ri) => row.forEach((v, ci) => put(ri + 1, ci, v)));
    }
  });
});

if (!newSlideIds.length) throw new Error('ADS_REPORT_FAILED - tidak ada halaman yang punya layout di base deck');

requests.push(...contentReqs);
requests.push({ updateSlidesPosition: { slideObjectIds: newSlideIds, insertionIndex: 0 } });
for (const s of pres.slides) requests.push({ deleteObject: { objectId: s.objectId } });

return [{ json: { presentationId: pres.presentationId, requests, imageJobs, warnings } }];

// automation/src/ads-image-jobs.js
// Satu item per gambar (creative / custom image) → node Slides "Ganti Gambar" dijalankan per item
// dengan continueRegularOutput: gambar yang gagal hanya jadi warning, laporan tetap jadi.
// Selalu keluarkan minimal 1 item (hasImage=false) supaya alur n8n tidak berhenti.

const r = $('Susun Request Slides').first().json;
const jobs = r.imageJobs || [];
if (!jobs.length) return [{ json: { hasImage: false, presentationId: r.presentationId } }];
return jobs.map((j) => ({ json: { hasImage: true, presentationId: r.presentationId, ref: j.ref, body: { requests: [{ replaceImage: j.replaceImage }] } } }));

// automation/src/ads-share-list.js
// Daftar penerima akses file Slides: owner workspace = writer (editor), penerima laporan = reader.
// Selalu minimal 1 item (hasEmail=false) supaya alur tidak berhenti.

const job = $('Auth & Normalize (Ads)').first().json;
const copy = $('Drive: Salin Base Deck').first().json;
const seen = new Set();
const items = [];
const add = (email, role) => {
  const e = String(email || '').trim().toLowerCase();
  if (!e || !e.includes('@') || seen.has(e)) return;
  seen.add(e);
  items.push({ json: { hasEmail: true, fileId: copy.id, body: { type: 'user', role, emailAddress: e } } });
};
add(job.owner && job.owner.email, 'writer');
for (const r of job.recipients || []) add(r, 'reader');
return items.length ? items : [{ json: { hasEmail: false, fileId: copy.id } }];

// automation/src/ads-prepare-callback.js
// Callback sukses ke backend (POST /api/ads/reports/callback, header X-Supermat-Key).
// pdfPath = tautan ekspor PDF Google Slides (bisa dibuka oleh owner/penerima yang diberi akses).

const job = $('Auth & Normalize (Ads)').first().json;
const proc = $('Parse Insight').first().json;
const render = $('Susun Request Slides').first().json;
const copy = $('Drive: Salin Base Deck').first().json;
const warnings = [...(proc.warnings || []), ...(render.warnings || [])];

const safeAll = (name) => {
  try {
    return $(name).all();
  } catch (e) {
    return []; // node tidak dieksekusi (cabang IF lain)
  }
};
const failed = (it) => it.json && (it.json.error || (it.json.statusCode && it.json.statusCode >= 400));
const imgIn = safeAll('Susun Request Gambar').filter((it) => it.json.hasImage);
safeAll('Slides: Ganti Gambar').forEach((it, i) => {
  if (failed(it)) warnings.push(`image_failed:${(imgIn[i] && imgIn[i].json.ref) || i}`);
});
const shareIn = safeAll('Daftar Akses').filter((it) => it.json.hasEmail);
safeAll('Drive: Bagikan Akses').forEach((it, i) => {
  if (failed(it)) warnings.push(`share_failed:${(shareIn[i] && shareIn[i].json.body.emailAddress) || i}`);
});
if (!shareIn.length) warnings.push('share_skipped:no_owner_email');

const id = copy.id;
return [{
  json: {
    callbackUrl: job.callbackUrl,
    callbackPayload: {
      requestId: job.requestId,
      reportId: job.reportId,
      status: 'ready',
      slidesUrl: `https://docs.google.com/presentation/d/${id}/edit`,
      slidesFileId: id,
      pdfPath: `https://docs.google.com/presentation/d/${id}/export/pdf`,
      summary: { ...proc.summary, spreadsheetId: $('Susun Data Grafik').first().json.spreadsheetId },
      aiPages: proc.aiPages || 0,
      warnings: [...new Set(warnings)].slice(0, 100)
    }
  }
}];

// automation/src/ads-callback-error.js
// Semua error output (Code/HTTP) bermuara ke sini → callback status 'error' supaya backend
// langsung me-refund kredit (tanpa menunggu timeout 15 menit).

const job = $('Auth & Normalize (Ads)').first().json;
const it = $input.first().json || {};
const raw = it.error && typeof it.error === 'object' ? (it.error.message || JSON.stringify(it.error)) : (it.error || it.message || 'unknown error');
const msg = String(raw);
// Deck milik user gagal disalin (belum dibagikan / dihapus) → kode khusus supaya UI bisa menjelaskan
let prev = '';
try { prev = $prevNode.name; } catch (e) { prev = ''; }
const code = /ADS_SOURCE_UNAVAILABLE/.test(msg)
  ? 'ADS_SOURCE_UNAVAILABLE'
  : (job.deckId && prev === 'Drive: Salin Base Deck' ? 'ADS_DECK_UNAVAILABLE' : 'ADS_REPORT_FAILED');

return [{
  json: {
    callbackUrl: job.callbackUrl,
    callbackPayload: {
      requestId: job.requestId,
      reportId: job.reportId,
      status: 'error',
      errorCode: code,
      // token tidak pernah ada di pesan error (dikirim via header), tetap dipotong supaya ringkas
      warnings: [`error:${msg.replace(/access_token=[^&\s]+/g, 'access_token=***').slice(0, 300)}`]
    }
  }
}];
